scene.background = null; // Will be set via CSS background color on canvas

const camera = new PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 200);
camera.position.set(0, 8, 16);
camera.lookAt(0, -3, 0);

// Get the canvas from the DOM (created by Vite's index.html)
