import {
  Scene,
  PerspectiveCamera,
  WebGLRenderer,
  Clock,
  EventDispatcher,
  ACESFilmicToneMapping,
} from 'three';
import { setupPostProcessing } from './PostProcessing';

export interface EngineCallbacks {
  update: (dt: number) => void;
  render?: () => void;
}

export class Engine extends EventDispatcher {
  private scene: Scene;
  private camera: PerspectiveCamera;
  private renderer: WebGLRenderer;
  private composer: any;
  private clock: Clock;
  private callbacks: EngineCallbacks;
  private animationId: number | null = null;
  private isPaused: boolean = false;

  constructor(
    canvas: HTMLCanvasElement,
    scene: Scene,
    camera: PerspectiveCamera,
    callbacks: EngineCallbacks
  ) {
    super();
    this.scene = scene;
    this.camera = camera;
    this.callbacks = callbacks;
    this.clock = new Clock();

    // Renderer setup
    this.renderer = new WebGLRenderer({
      canvas,
      antialias: true,
      alpha: false,
      powerPreference: 'high-performance',
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.setSize(
      window.innerWidth,
      window.innerHeight
    );
    this.renderer.toneMapping = ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;

    // Post-processing
    this.composer = setupPostProcessing(this.renderer, scene, camera);

    // Handle resize
    const onResize = (): void => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      this.camera.aspect = w / h;
      this.camera.updateProjectionMatrix();
      this.renderer.setSize(w, h);
      if (this.composer) {
        this.composer.setSize(w, h);
      }
    };
    window.addEventListener('resize', onResize);

    // Visibility change — pause when hidden
    const onVisibilityChange = (): void => {
      this.isPaused = document.hidden;
    };
    document.addEventListener('visibilitychange', onVisibilityChange);

    this.startLoop();
  }

  private startLoop(): void {
    const loop = (): void => {
      this.animationId = requestAnimationFrame(loop);
      if (this.isPaused) return;

      const dt = Math.min(this.clock.getDelta(), 0.1); // cap at 100ms to prevent spiral
      this.callbacks.update(dt);
      if (this.callbacks.render) {
        this.callbacks.render();
      } else {
        this.renderer.render(this.scene, this.camera);
      }
    };
    this.animationId = requestAnimationFrame(loop);
  }

  /** Update the composer's render target size */
  resize(): void {
    const w = window.innerWidth;
    const h = window.innerHeight;
    if (this.composer) {
      this.composer.setSize(w, h);
    }
  }

  /** Graceful shutdown — dispose all resources */
  dispose(): void {
    if (this.animationId !== null) {
      cancelAnimationFrame(this.animationId);
      this.animationId = null;
    }
    this.renderer.dispose();
    this.scene.traverse((obj) => {
      if ((obj as any).geometry) (obj as any).geometry.dispose();
      if ((obj as any).material) {
        const mats = Array.isArray((obj as any).material)
          ? (obj as any).material
          : [(obj as any).material];
        for (const mat of mats) {
          if (mat.dispose) mat.dispose();
        }
      }
    });
  }

  /** Get the renderer instance */
  getRenderer(): WebGLRenderer {
    return this.renderer;
  }

  /** Get the composer instance */
  getComposer(): any {
    return this.composer;
  }

  /** Get the scene */
  getScene(): Scene {
    return this.scene;
  }

  /** Get the camera */
  getCamera(): PerspectiveCamera {
    return this.camera;
  }
}

/**
 * Unified dual-input controller supporting Keyboard + Gamepad API.
 */

import { GamepadState } from './Gamepad';

export type ActionName = 'moveLeft' | 'moveRight' | 'fire' | 'pause';

interface ActionMap {
  [key: string]: boolean;
}

export class InputManager {
  private gamepadState: GamepadState;
  private keysDown: Set<string> = new Set();
  private actions: ActionMap = {};
  private actionMap: Record<ActionName, string[]>;
  private gamepadIndex: number = 0;
  private lastPollTime: number = 0;

  constructor() {
    this.gamepadState = new GamepadState();
    this.actionMap = {
      moveLeft: ['ArrowLeft', 'KeyA'],
      moveRight: ['ArrowRight', 'KeyD'],
      fire: ['Space', 'Enter', 'ShiftLeft', 'ShiftRight'],
      pause: ['Escape', 'KeyP'],
    };
    this.setupKeyboardListeners();
  }

  private setupKeyboardListeners(): void {
    window.addEventListener('keydown', (e: KeyboardEvent) => {
      this.keysDown.add(e.code);
      e.preventDefault();
    });

    window.addEventListener('keyup', (e: KeyboardEvent) => {
      this.keysDown.delete(e.code);
    });
  }

  /** Poll all inputs and update the action map. Call once per frame. */
  poll(): ActionMap {
    const result: ActionMap = {};

    // Evaluate each action against keyboard state
    for (const [action, keys] of Object.entries(this.actionMap)) {
      let pressed = false;
      for (const key of keys) {
        if (this.keysDown.has(key)) {
          pressed = true;
          break;
        }
      }
      result[action] = pressed;
    }

    // Evaluate each action against gamepad state
    const gp = this.gamepadState.poll();
    if (gp && this.gamepadState.isConnected(gp)) {
      // Gamepad axes for movement (axis 0 is left stick X)
      const axisX = this.gamepadState.getAxis(gp, 0);
      if (result['moveLeft'] || axisX < -0.15) result['moveLeft'] = true;
      if (result['moveRight'] || axisX > 0.15) result['moveRight'] = true;

      // Gamepad buttons for fire (button 0 = A/Cross, button 7 = Right Trigger)
      if (result['fire'] || this.gamepadState.getButtonHeld(gp, 0) || this.gamepadState.getButtonHeld(gp, 7)) {
        result['fire'] = true;
      }

      // Pause
      if (this.gamepadState.getButtonJustPressed(gp, 12) || this.gamepadState.getButtonJustPressed(gp, 8)) {
        result['pause'] = true;
      }
    }

    this.actions = result;
    return result;
  }

  /** Get the current state of an action. */
  getAction(action: ActionName): boolean {
    return !!this.actions[action];
  }

  /** Check if a gamepad is currently connected. */
  hasGamepad(): boolean {
    const gp = this.gamepadState.poll();
    return gp !== null && this.gamepadState.isConnected(gp);
  }

  /** Reset all input state (useful on menu transitions). */
  reset(): void {
    this.keysDown.clear();
    this.actions = {};
    this.gamepadState.reset();
  }

  /** Dispose of event listeners. */
  dispose(): void {
    window.removeEventListener('keydown', this.onKeydown);
    window.removeEventListener('keyup', this.onKeyup);
  }

  private onKeydown = (e: KeyboardEvent): void => {
    this.keysDown.add(e.code);
    e.preventDefault();
  };

  private onKeyup = (e: KeyboardEvent): void => {
    this.keysDown.delete(e.code);
  };
}

/**
 * Web Audio API synthesized SFX engine.
 * All sounds are generated procedurally — no external audio files.
 */

export class Synth {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;

  constructor() {
    try {
      this.ctx = new AudioContext();
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = 0.3;
      this.masterGain.connect(this.ctx.destination);
    } catch (e) {
      console.warn('Web Audio API not available:', e);
    }
  }

  private ensureContext(): boolean {
    if (!this.ctx) return false;
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    return true;
  }

  /** Player ship laser shot */
  playShoot(): void {
    if (!this.ensureContext() || !this.ctx || !this.masterGain) return;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(880, this.ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(220, this.ctx.currentTime + 0.15);
    gain.gain.setValueAtTime(0.3, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.15);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start();
    osc.stop(this.ctx.currentTime + 0.15);
  }

  /** Alien hit — short high-pitched blip */
  playAlienHit(type: number = 0): void {
    if (!this.ensureContext() || !this.ctx || !this.masterGain) return;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const freqs = [1200, 900, 700];
    osc.type = 'square';
    osc.frequency.setValueAtTime(freqs[type] || 900, this.ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(200, this.ctx.currentTime + 0.1);
    gain.gain.setValueAtTime(0.2, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.1);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start();
    osc.stop(this.ctx.currentTime + 0.1);
  }

  /** Explosion — noise burst */
  playExplosion(): void {
    if (!this.ensureContext() || !this.ctx || !this.masterGain) return;

    const bufferSize = this.ctx.sampleRate * 0.3;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufferSize, 2);
    }

    const source = this.ctx.createBufferSource();
    source.buffer = buffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(3000, this.ctx.currentTime);
    filter.frequency.exponentialRampToValueAtTime(100, this.ctx.currentTime + 0.3);

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.4, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.3);

    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);
    source.start();
  }

  /** Player hit — low rumble */
  playPlayerHit(): void {
    if (!this.ensureContext() || !this.ctx || !this.masterGain) return;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(150, this.ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(40, this.ctx.currentTime + 0.4);
    gain.gain.setValueAtTime(0.5, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.4);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start();
    osc.stop(this.ctx.currentTime + 0.4);
  }

  /** UFO bonus — ascending tone */
  playUFOBeep(): void {
    if (!this.ensureContext() || !this.ctx || !this.masterGain) return;

    const now = this.ctx.currentTime;
    for (let i = 0; i < 3; i++) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(440 + i * 200, now + i * 0.1);
      gain.gain.setValueAtTime(0.15, now + i * 0.1);
      gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.1 + 0.08);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(now + i * 0.1);
      osc.stop(now + i * 0.1 + 0.08);
    }
  }

  /** Wave transition — triumphant chord */
  playWaveComplete(): void {
    if (!this.ensureContext() || !this.ctx || !this.masterGain) return;

    const now = this.ctx.currentTime;
    const freqs = [523.25, 659.25, 783.99]; // C major chord
    for (const freq of freqs) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'square';
      osc.frequency.setValueAtTime(freq, now);
      gain.gain.setValueAtTime(0.15, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.8);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(now);
      osc.stop(now + 0.8);
    }
  }

  /** Game over — descending tones */
  playGameOver(): void {
    if (!this.ensureContext() || !this.ctx || !this.masterGain) return;

    const now = this.ctx.currentTime;
    const freqs = [400, 350, 300, 200];
    for (let i = 0; i < freqs.length; i++) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(freqs[i], now + i * 0.2);
      gain.gain.setValueAtTime(0.2, now + i * 0.2);
      gain.gain.exponentialRampToValueAtTime(0.001, now + i * 0.2 + 0.3);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(now + i * 0.2);
      osc.stop(now + i * 0.2 + 0.3);
    }
  }

  /** Shield crackle */
  playShieldHit(): void {
    if (!this.ensureContext() || !this.ctx || !this.masterGain) return;

    const bufferSize = this.ctx.sampleRate * 0.1;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufferSize, 4);
    }

    const source = this.ctx.createBufferSource();
    source.buffer = buffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.value = 2000;

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.15, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.1);

    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);
    source.start();
  }

  /** Reset audio context for reuse */
  reset(): void {
    if (this.ctx) {
      this.ctx.close();
      this.ctx = null;
      this.masterGain = null;
    }
  }
}

/**
 * Procedural music engine using Web Audio API oscillators.
 * Generates a looping retro-futuristic soundtrack with no external audio files.
 */

export class MusicEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private isPlaying = false;
  private intervalId: number | null = null;
  private intensity: number = 0.5; // 0-1, affects note density and volume

  constructor() {
    try {
      this.ctx = new AudioContext();
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = 0.12;
      this.masterGain.connect(this.ctx.destination);
    } catch (e) {
      console.warn('Web Audio API not available for music:', e);
    }
  }

  private ensureContext(): boolean {
    if (!this.ctx) return false;
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    return true;
  }

  /** Start the procedural music loop */
  start(): void {
    if (!this.ensureContext() || !this.ctx || !this.masterGain) return;
    if (this.isPlaying) return;
    this.isPlaying = true;

    const bpm = 120;
    const beatInterval = 60 / bpm; // seconds per beat

    // Bass line pattern — pentatonic scale notes
    const bassNotes = [65.41, 77.78, 98.00, 110.00, 130.81]; // C2, D2, F2, G2, A2

    // Arpeggio pattern — higher octave
    const arpNotes = [261.63, 329.63, 392.00, 523.25, 659.25]; // C4, E4, G4, C5, E5

    let beatCount = 0;
    let arpIndex = 0;

    const playBeat = () => {
      if (!this.isPlaying || !this.ctx || !this.masterGain) return;

      const now = this.ctx.currentTime;

      // Bass on every other beat
      if (beatCount % 2 === 0) {
        const bassOsc = this.ctx.createOscillator();
        const bassGain = this.ctx.createGain();
        bassOsc.type = 'square';
        const noteIdx = Math.floor(beatCount / 4) % bassNotes.length;
        bassOsc.frequency.setValueAtTime(bassNotes[noteIdx], now);
        bassGain.gain.setValueAtTime(0.15 * this.intensity, now);
        bassGain.gain.exponentialRampToValueAtTime(0.001, now + beatInterval * 1.8);
        bassOsc.connect(bassGain);
        bassGain.connect(this.masterGain);
        bassOsc.start(now);
        bassOsc.stop(now + beatInterval * 2);
      }

      // Arpeggio on every beat with intensity-based probability
      if (Math.random() < this.intensity) {
        const arpOsc = this.ctx.createOscillator();
        const arpGain = this.ctx.createGain();
        arpOsc.type = 'sawtooth';
        const noteIdx = arpIndex % arpNotes.length;
        arpOsc.frequency.setValueAtTime(arpNotes[noteIdx], now);
        arpGain.gain.setValueAtTime(0.06 * this.intensity, now);
        arpGain.gain.exponentialRampToValueAtTime(0.001, now + beatInterval * 0.8);
        arpOsc.connect(arpGain);
        arpGain.connect(this.masterGain);
        arpOsc.start(now);
        arpOsc.stop(now + beatInterval);

        arpIndex++;
      }

      // Percussion — noise burst on beats 1 and 3
      if (beatCount % 4 === 0 || beatCount % 4 === 2) {
        this.playPercussion(now, beatCount % 4 === 0 ? 'kick' : 'hihat');
      }

      // Hi-hat on off-beats at higher intensity
      if (this.intensity > 0.7 && beatCount % 2 === 1) {
        this.playPercussion(now, 'hihat');
      }

      beatCount++;
    };

    playBeat(); // Play first beat immediately
    this.intervalId = window.setInterval(playBeat, beatInterval * 1000);
  }

  private playPercussion(time: number, type: 'kick' | 'hihat'): void {
    if (!this.ctx || !this.masterGain) return;

    const bufferSize = this.ctx.sampleRate * 0.15;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);

    for (let i = 0; i < bufferSize; i++) {
      if (type === 'kick') {
        // Low-frequency noise burst for kick
        const freq = 60 * Math.exp(-i / (this.ctx.sampleRate * 0.02));
        data[i] = Math.sin(2 * Math.PI * freq * i / this.ctx.sampleRate) *
                  Math.pow(1 - i / bufferSize, 3);
      } else {
        // High-frequency noise for hi-hat
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufferSize, 6);
      }
    }

    const source = this.ctx.createBufferSource();
    source.buffer = buffer;

    const gain = this.ctx.createGain();
    if (type === 'kick') {
      gain.gain.setValueAtTime(0.2 * this.intensity, time);
    } else {
      gain.gain.setValueAtTime(0.08 * this.intensity, time);
    }
    gain.gain.exponentialRampToValueAtTime(0.001, time + 0.15);

    source.connect(gain);
    gain.connect(this.masterGain);
    source.start(time);
  }

  /** Stop the music */
  stop(): void {
    this.isPlaying = false;
    if (this.intervalId !== null) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  /** Set intensity level (0-1). Higher = more notes, louder. */
  setIntensity(level: number): void {
    this.intensity = Math.max(0, Math.min(1, level));
    if (this.masterGain) {
      this.masterGain.gain.value = 0.12 * (0.5 + this.intensity * 0.5);
    }
  }

  /** Get current intensity */
  getIntensity(): number {
    return this.intensity;
  }

  /** Reset audio context for reuse */
  reset(): void {
    this.stop();
    if (this.ctx) {
      this.ctx.close();
      this.ctx = null;
      this.masterGain = null;
    }
  }
}

